#!/usr/bin/env python3
import hashlib, json, sys
from pathlib import Path

def canon(v): return json.dumps(v, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
def digest(v): return hashlib.sha256(canon(v).encode("utf-8")).hexdigest()
def load(p): return json.loads(Path(p).read_text(encoding="utf-8"))

def independent_stage_expectations(data):
    authorities = {x["id"] for x in data["authorities"]}
    b_rows = []
    for p in data["legal_propositions"]:
        if any(x not in authorities for x in p["authority_ids"]): c,s,r = "UNRESOLVED_MISSING_AUTHORITY","UNRESOLVED","A referenced authority is absent from the closed-world record."
        elif p["kind"] == "holding": c,s,r = "SUPPORTED_HOLDING","SUPPORTED","The supplied synthetic holding supports the proposition within the stated posture."
        elif p["kind"] == "dicta": c,s,r = "DICTA_ONLY","LIMITED","The proposition is not a necessary holding in the supplied record."
        elif p["kind"] == "inference": c,s,r = "INFERENCE_REQUIRES_RECORD","INFERENCE","The proposition requires application to the factual record and is not established by authority alone."
        else: c,s,r = "UNSUPPORTED","UNSUPPORTED","The proposition is not supported by the supplied closed-world authorities."
        b_rows.append({"proposition_id":p["id"],"authority_ids":p["authority_ids"],"classification":c,"status":s,"reason":r})
    brief_payload={"schema":"briefwise-integrated-stage-v1","matter_id":data["matter_id"],"stage":"BriefWise","jurisdiction":data["jurisdiction"],"procedural_posture":data["procedural_posture"],"burden_and_standard":data["burden_and_standard"],"authority_map":b_rows,"stage_disposition":"REVIEW_REQUIRED","unresolved":[x["proposition_id"] for x in b_rows if x["status"]=="UNRESOLVED"],"unsupported":[x["proposition_id"] for x in b_rows if x["status"]=="UNSUPPORTED"],"inferences":[x["proposition_id"] for x in b_rows if x["status"]=="INFERENCE"],"non_claims":["Synthetic authorities only.","Authority binding does not establish product identity, exposure, dose, causation, or liability."]}
    brief=dict(brief_payload, canonical_record_sha256=digest(brief_payload))
    t={x["id"]:x for x in data["transcript"]}; expected={"T-001":"10:4-10:10","T-002":"27:2-27:8","T-003":"34:1-34:6","T-004":"12:3-12:8","T-005":"15:1-15:6","T-006":"41:1-41:5","T-007":"45:3-45:7"}; issues=[k for k,v in expected.items() if k not in t or t[k].get("page_line")!=v]; a,b=t.get("T-001"),t.get("T-002"); contradiction=bool(a and b and not issues and a["speaker"]==b["speaker"] and "personally replaced" in a["answer"].lower() and "did not perform any repair" in b["answer"].lower() and "north plant" in a["answer"].lower() and "north plant" in b["answer"].lower() and "2014" in a["answer"] and "2014" in b["answer"])
    findings=[{"id":"C-001","type":"DIRECT_CONTRADICTION" if contradiction else ("UNRESOLVED_SOURCE_BINDING" if issues else "NOT_ESTABLISHED"),"entries":["T-001","T-002"],"speaker":"Witness A","explanation":"The same witness gives opposite answers about the same repair at the same site and time." if contradiction else "The canonical source binding or same-event predicate is not established."},{"id":"C-002","type":"AMBIGUITY","entries":["T-003"],"speaker":"Witness A","explanation":"Probably gray plus lack of clear recollection is uncertainty, not contradiction."},{"id":"C-003","type":"NEGATIVE_CONTROL_NOT_CONTRADICTION","entries":["T-004","T-005"],"speaker":"Witness B","explanation":"Lack of observation and inability to identify the repairer do not negate another witness's account."},{"id":"C-004","type":"CHARACTERIZATION_NOT_ADMISSION","entries":["T-006"],"speaker":"Counsel","explanation":"A characterized question without an answer is not an admission."},{"id":"C-005","type":"OMISSION_MISSING_FOUNDATION","entries":["T-007"],"speaker":"Witness A","explanation":"Failure to recall a manufacturer name does not establish an opposing fact."}]
    depo_payload={"schema":"depobot-integrated-stage-v1","matter_id":data["matter_id"],"stage":"DepoBot","source_binding_valid":not issues,"binding_issues":issues,"findings":findings,"stage_disposition":"REVIEW_REQUIRED","unresolved":["The contradiction may require credibility and foundation review."],"non_claims":["No credibility determination is made.","No synthetic testimony is treated as a real admission."]}; depo=dict(depo_payload,canonical_record_sha256=digest(depo_payload))
    recs=data["evidence_records"]; products={r.get("product_id") for r in recs if r["kind"]=="product_reference"}; links={(r.get("product_id"),r.get("manufacturer")) for r in recs if r["kind"]=="manufacturer_reference"}; matches=sorted(p for p in products if any(pid==p for pid,_ in links)); unsupported=[r["id"] for r in recs if r["kind"] in ("material_assertion","material_specification") and r.get("source")!="manufacturer_specification"]; injections=[r["id"] for r in recs if r["kind"]=="manual_override"]; rows=[{"dimension":"product_identification","status":"MATCH" if matches else "REVIEW","basis":matches or ["No shared product identifier links the product to a manufacturer."]},{"dimension":"component_identification","status":"REVIEW","basis":["The gasket is referenced but not tied to a component specification or supplier record."]},{"dimension":"material_content","status":"UNCERTAIN","basis":["No manufacturer specification establishes the asserted material content."]},{"dimension":"worksite_chronology","status":"DISPUTED","basis":["The work order and testimony contain a genuine repair-history conflict."]},{"dimension":"exposure","status":"REVIEW","basis":["Handling is alleged, but the handled component is not sufficiently identified as the asserted material."]},{"dimension":"dose","status":"UNCERTAIN","basis":["No quantified dose, duration, or measurement is supplied."]},{"dimension":"causation","status":"UNCERTAIN","basis":["The synthetic expert record supplies no causation opinion."]},{"dimension":"legal_liability","status":"INSUFFICIENT","basis":["The record does not establish every required liability link."]}]; pid_payload={"schema":"pidbot-integrated-stage-v1","matter_id":data["matter_id"],"stage":"PIDBot","separation_preserved":["product_identification","component_identification","material_content","worksite_chronology","exposure","dose","causation","legal_liability"],"evidence_matrix":rows,"unsupported_material_assertions":unsupported,"unsupported_manual_injections":injections,"stage_disposition":"REVIEW_REQUIRED","non_claims":["Product identification does not establish material content, exposure, dose, causation, or liability.","All records and outcomes are synthetic."]}; pid=dict(pid_payload,canonical_record_sha256=digest(pid_payload))
    return brief,depo,pid

def main():
    package=Path(__file__).resolve().parent; run_dir=Path(sys.argv[sys.argv.index("--run-dir")+1]) if "--run-dir" in sys.argv else package/"run_1"; expected=package/"expected_stage_outputs"; final_expected=load(package/"expected_final_chain.json"); data=load(package/"input.json"); brief,depo,pid=independent_stage_expectations(data); expected_map={"briefwise":brief,"depobot":depo,"pidbot":pid}; checks={}
    for k,v in expected_map.items(): checks[f"independent_{k}_matches_expected"] = v==load(expected/f"{k}.json")
    checks["independent_final_expected_hash"] = final_expected["final_chain_sha256"] == digest({k:v for k,v in final_expected.items() if k!="final_chain_sha256"})
    checks["run_matches_expected"] = all(load(run_dir/f"{k}.json")==load(expected/f"{k}.json") for k in ("briefwise","depobot","pidbot")) and load(run_dir/"final_chain.json")==final_expected
    if "run_2" in [p.name for p in package.iterdir() if p.is_dir()]: checks["two_runs_identical"] = all(load(package/"run_1"/f"{k}.json")==load(package/"run_2"/f"{k}.json") for k in ("briefwise","depobot","pidbot","final_chain"))
    else: checks["two_runs_identical"] = False
    checks["negative_control_is_preserved"] = any(x["type"]=="NEGATIVE_CONTROL_NOT_CONTRADICTION" for x in load(expected/"depobot.json")["findings"])
    checks["contradiction_is_preserved"] = "C-001" in load(package/"expected_final_chain.json")["preserved_contradictions"]
    checks["material_dose_causation_not_upgraded"] = all(load(expected/"pidbot.json")["evidence_matrix"][i]["status"] in ("UNCERTAIN","REVIEW") for i in (2,5,6))
    result={"verifier":"PASS" if all(checks.values()) else "FAIL","checks":checks,"scope":"closed-world synthetic integrated chain"}; print(json.dumps(result,sort_keys=True,indent=2));
    if "--run-dir" not in sys.argv: (package/"independent_evaluator_result.json").write_text(json.dumps(result,sort_keys=True,indent=2)+"\n")
    raise SystemExit(0 if result["verifier"]=="PASS" else 1)

if __name__=="__main__": main()
